 const hatGeo = new THREE.CylinderGeometry(0.4,0.4,0.1,16);
 const hatMat = new THREE.MeshStandardMaterial({color:0x4caf50});
 const hat = new THREE.Mesh(hatGeo,hatMat);
 hat.position.y = size/2 + 0.6;
 mesh.add(hat);
 scene.add(mesh);
 robots.push({mesh, health:1});
}
function updateScore(delta){
 score += delta;
 scoreEl.textContent = score;
}
function loseLife(){
 lives--;
 livesEl.textContent = lives;
 if(lives<=0){
 alert('המשחק נגמר! ניקוד סופי: '+score);
 window.location.reload();
 }
}

// ------------------- קלט מקלדת -------------------
const keys = {w:false,a:false,s:false,d:false,space:false};
document.addEventListener('keydown',e=>{
 switch(e.code){
 case 'KeyW':case 'ArrowUp': keys.w=true; break;
 case 'KeyA':case 'ArrowLeft': keys.a=true; break;
 case 'KeyS':case 'ArrowDown': keys.s=true; break;
 case 'KeyD':case 'ArrowRight': keys.d=true; break;
 case 'Space': keys.space=true; break;
 }
});
document.addEventListener('keyup',e=>{
 switch(e.code){
 case 'KeyW':case 'ArrowUp': keys.w=false; break;
 case 'KeyA':case 'ArrowLeft': keys.a=false; break;
 case 'KeyS':case 'ArrowDown': keys.s=false; break;
 case 'KeyD':case 'ArrowRight': keys.d=false; break;
 case 'Space': keys.space=false; break;
 }
});

// ------------------- לולאת משחק -------------------
let lastSpawn = 0;
function animate(time){
 const delta = Math.min(0.05, renderer.info.render.frameTime/1000);

 // תנועה של השחקן
 if(controls.isLocked){
 const move = new THREE.Vector3();
 if(keys.w) move.z -= 1;
 if(keys.s) move.z += 1;
 if(keys.a) move.x -= 1;
 if(keys.d) move.x += 1;
 move.normalize().multiplyScalar(PLAYER_SPEED*delta);
 const yaw = controls.getObject().rotation.y;
 const sin = Math.sin(yaw), cos = Math.cos(yaw);
 const dx = move.x*cos - move.z*sin;
 const dz = move.x*sin + move.z*cos;
 controls.getObject().position.x += dx;
 controls.getObject().position.z += dz;
 }

