 createBullet(camera.position.clone().add(new THREE.Vector3(0,0.2,0)), dir);
 setTimeout(()=>canShoot=true,200); // קצב אש
 }

 // עדכון קליעים
 for(let i=bullets.length-1;i>=0;i--){
 const b = bullets[i];
 b.mesh.position.addScaledVector(b.dir,BULLET_SPEED*delta);
 // מחיקת קליע אחרי 2 שניות או אם הוא מחוץ לשטח
 if(b.mesh.position.distanceTo(camera.position)>100){
 scene.remove(b.mesh);
 bullets.splice(i,1);
 }
 }

 // עדכון רובוטים
 for(let i=robots.length-1;i>=0;i--){
 const r = robots[i];
 const dir = new THREE.Vector3().subVectors(camera.position,r.mesh.position).normalize();
 r.mesh.position.addScaledVector(dir,ROBOT_SPEED*delta);
 // בדיקת פגיעה בקליע
 for(let j=bullets.length-1;j>=0;j--){
 const b = bullets[j];
 if(b.mesh.position.distanceTo(r.mesh.position)<0.5){
 // פגיעה – מחיקת רובוט וקליע
 scene.remove(r.mesh);
 robots.splice(i,1);
 scene.remove(b.mesh);
 bullets.splice(j,1);
